@namespace sv_72b28f8b76cf47588d0028df42020100.Components.Pages.JobApplication

<div class="step-content">
    <h2>References</h2>
    <p class="step-description">Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];

        <div class="reference-entry">
            <div class="reference-entry__header">
                <h4>Reference @(index + 1)</h4>
                @if (References.Count > 2)
                {
                    <button class="btn btn-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>

            <div class="form-group">
                <label>Name *</label>
                <input type="text" value="@reference.Name" @oninput="e => UpdateReference(index, reference with { Name = e.Value?.ToString() ?? "" })" class="form-control" />
            </div>

            <div class="form-group">
                <label>Relationship *</label>
                <input type="text" value="@reference.Relationship" @oninput="e => UpdateReference(index, reference with { Relationship = e.Value?.ToString() ?? "" })" class="form-control" placeholder="e.g., Former Manager" />
            </div>

            <div class="form-row">
                <div class="form-group form-group--half">
                    <label>Email *</label>
                    <input type="email" value="@reference.Email" @oninput="e => UpdateReference(index, reference with { Email = e.Value?.ToString() ?? "" })" class="form-control" />
                </div>
                <div class="form-group form-group--half">
                    <label>Phone *</label>
                    <input type="tel" value="@reference.Phone" @oninput="e => UpdateReference(index, reference with { Phone = e.Value?.ToString() ?? "" })" class="form-control" />
                </div>
            </div>
        </div>
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? _validationError;

    protected override void OnParametersSet()
    {
        if (References.Count < 2)
        {
            while (References.Count < 2)
            {
                References.Add(ReferenceModel.Empty());
            }
        }
    }

    private void UpdateReference(int index, ReferenceModel reference)
    {
        References[index] = reference;
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(ReferenceModel.Empty());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        _validationError = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _validationError = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }

    public record ReferenceModel(string Name, string Relationship, string Email, string Phone)
    {
        public static ReferenceModel Empty() => new("", "", "", "");
    }
}

