toolArgs.file_text:
.application-container {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1.5rem;
}

.application-container h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2.5rem;
    padding: 1rem 0;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    transition: opacity 0.2s;
}

.step:disabled {
    cursor: not-allowed;
}

.step__marker {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    margin-bottom: 0.4rem;
    transition: all 0.2s;
}

.step--current .step__marker {
    background: #4361ee;
    color: white;
}

.step--completed .step__marker {
    background: #2ec4b6;
    color: white;
}

.step--future .step__marker {
    background: #e0e0e0;
    color: #999;
}

.step__label {
    font-size: 0.75rem;
    color: #666;
    white-space: nowrap;
}

.step--current .step__label {
    color: #4361ee;
    font-weight: 600;
}

.step--completed .step__label {
    color: #2ec4b6;
}

.step--future .step__label {
    color: #999;
}

.step__connector {
    width: 30px;
    height: 2px;
    background: #e0e0e0;
    align-self: center;
    margin-bottom: 1.2rem;
}

.step__connector--completed {
    background: #2ec4b6;
}

/* Step Content */
.step-content {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
}

.step-content h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.step-description {
    color: #666;
    margin-bottom: 1.5rem;
}

/* Form Controls */
.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.4rem;
    color: #333;
    font-size: 0.9rem;
}

.form-control {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-control:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: flex;
    gap: 1rem;
}

.form-group--half {
    flex: 1;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    margin-top: 0.4rem;
    font-weight: normal !important;
    font-size: 0.85rem !important;
    color: #555 !important;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

.btn {
    padding: 0.7rem 1.5rem;
    border-radius: 6px;
    font-size: 0.95rem;
    font-weight: 500;
    cursor: pointer;
    border: none;
    transition: all 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #4361ee;
    color: white;
    margin-left: auto;
}

.btn-primary:hover:not(:disabled) {
    background: #3651d4;
}

.btn-outline {
    background: transparent;
    border: 1px solid #ddd;
    color: #555;
}

.btn-outline:hover {
    border-color: #999;
    color: #333;
}

.btn-secondary {
    background: #f0f0f0;
    color: #333;
    margin-bottom: 1.5rem;
}

.btn-secondary:hover {
    background: #e0e0e0;
}

.btn-danger {
    background: #e63946;
    color: white;
}

.btn-danger:hover {
    background: #c62d39;
}

.btn-sm {
    padding: 0.35rem 0.8rem;
    font-size: 0.8rem;
}

.btn-link {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.85rem;
    text-decoration: underline;
    padding: 0;
}

.btn-link:hover {
    color: #3651d4;
}

.btn-submit {
    padding: 0.8rem 2rem;
    font-size: 1rem;
}

/* Work Entry */
.work-entry {
    border: 1px solid #eee;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1.25rem;
    background: #fafafa;
}

.work-entry__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry__header h4 {
    margin: 0;
    color: #333;
}

/* Reference Entry */
.reference-entry {
    border: 1px solid #eee;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1.25rem;
    background: #fafafa;
}

.reference-entry__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.reference-entry__header h4 {
    margin: 0;
    color: #333;
}

/* Cover Letter */
.cover-letter-textarea {
    min-height: 250px;
    resize: vertical;
}

.char-count {
    display: block;
    text-align: right;
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.4rem;
}

.char-count--warning {
    color: #e63946;
    font-weight: 500;
}

/* Review Step */
.review-section {
    border: 1px solid #eee;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1.25rem;
}

.review-section__header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-section__header h3 {
    margin: 0;
    font-size: 1.05rem;
    color: #1a1a2e;
}

.review-list {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-list dt {
    font-weight: 500;
    color: #555;
}

.review-list dd {
    margin: 0;
    color: #333;
}

.review-work-entry {
    padding: 0.75rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child {
    border-bottom: none;
}

.review-dates {
    font-size: 0.85rem;
    color: #666;
}

.review-description {
    margin: 0.4rem 0 0;
    font-size: 0.9rem;
    color: #555;
}

.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-reference:last-child {
    border-bottom: none;
}

.review-cover-letter {
    white-space: pre-wrap;
    color: #333;
    line-height: 1.6;
}

/* Validation */
.validation-summary {
    background: #fff0f0;
    border: 1px solid #ffcdd2;
    color: #c62828;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    margin-top: 1rem;
    font-size: 0.9rem;
}

.field-error {
    color: #e63946;
    font-size: 0.8rem;
    margin-top: 0.25rem;
    display: block;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 2rem;
}

.submission-confirmation h3 {
    color: #2ec4b6;
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.submission-confirmation p {
    color: #555;
    font-size: 1.05rem;
}

