    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private void Update(WorkEntryModel updated) => OnChanged.InvokeAsync(updated);

    private void OnCompanyChanged(ChangeEventArgs e) =>
        Update(Entry with { Company = e.Value?.ToString() ?? "" });

    private void OnTitleChanged(ChangeEventArgs e) =>
        Update(Entry with { Title = e.Value?.ToString() ?? "" });

    private void OnStartDateChanged(ChangeEventArgs e) =>
        Update(Entry with { StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : Entry.StartDate });

    private void OnEndDateChanged(ChangeEventArgs e) =>
        Update(Entry with { EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null });

    private void OnIsCurrentChanged(ChangeEventArgs e) =>
        Update(Entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = null });

    private void OnDescriptionChanged(ChangeEventArgs e) =>
        Update(Entry with { Description = e.Value?.ToString() ?? "" });

    public record WorkEntryModel(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description)
    {
        public static WorkEntryModel Empty() => new("", "", DateTime.Today, null, false, "");
    }
}

